package com.devsphere.ui;

import com.devsphere.dao.*;import com.devsphere.model.*;import com.devsphere.service.*;
import javax.swing.*;import java.awt.*;import java.sql.SQLException;

public class IssuesPanel extends JPanel {
    private static final Color NAVY=new Color(24,39,75),BLUE=new Color(54,104,220),BG=new Color(246,248,252);
    private final IssueService service;private final Session session;private final DefaultListModel<Issue> model=new DefaultListModel<>();private final JList<Issue> list=new JList<>(model);private final JTextField search=new JTextField(12);private final JComboBox<Object> status=new JComboBox<>();private final JComboBox<Object> priority=new JComboBox<>();private final JComboBox<Object> type=new JComboBox<>();private final JComboBox<AssigneeChoice> assignee=new JComboBox<>();private final JLabel footer=new JLabel();
    public IssuesPanel(IssueService service,Session session){this.service=service;this.session=session;setLayout(new BorderLayout(0,10));setBackground(UiStyle.BACKGROUND);setBorder(BorderFactory.createEmptyBorder(24,36,30,36));add(header(),BorderLayout.NORTH);list.setCellRenderer(new Renderer());list.setFixedCellHeight(74);list.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(e.getClickCount()==2)open();}});add(new JScrollPane(list),BorderLayout.CENTER);add(footer,BorderLayout.SOUTH);refresh();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JLabel title=UiStyle.heading("Issues");p.add(title,BorderLayout.WEST);JPanel f=new JPanel(new FlowLayout(FlowLayout.RIGHT,5,0));f.setOpaque(false);f.add(new JLabel("Search"));f.add(search);fill(status,IssueStatus.values(),"Status");fill(priority,IssuePriority.values(),"Priority");fill(type,IssueType.values(),"Type");assignee.addItem(new AssigneeChoice(null,"All assignees"));f.add(status);f.add(priority);f.add(type);f.add(assignee);JButton apply=new JButton("Filter");UiStyle.button(apply);apply.addActionListener(e->refresh());JButton create=UiStyle.primaryButton("Create issue");create.addActionListener(e->create());f.add(apply);f.add(create);p.add(f,BorderLayout.EAST);return p;}
    private void fill(JComboBox<Object> box,Object[] values,String first){box.addItem(first);for(Object v:values)box.addItem(v);}
    public void refresh(){try{IssueFilter filter=new IssueFilter(search.getText(),selected(status,IssueStatus.class),selected(priority,IssuePriority.class),selected(type,IssueType.class),null);java.util.List<Issue> loaded=service.list(session,filter);Long selectedAssignee=assignee.getSelectedItem() instanceof AssigneeChoice a?a.id:null;java.util.Set<Long> ids=new java.util.LinkedHashSet<>();for(Issue i:loaded)if(i.assigneeId()!=null)ids.add(i.assigneeId());AssigneeChoice current=(AssigneeChoice)assignee.getSelectedItem();assignee.removeAllItems();assignee.addItem(new AssigneeChoice(null,"All assignees"));for(Issue i:loaded)if(i.assigneeId()!=null&&!containsAssignee(i.assigneeId()))assignee.addItem(new AssigneeChoice(i.assigneeId(),i.assigneeUsername()));if(selectedAssignee!=null)for(int n=0;n<assignee.getItemCount();n++)if(java.util.Objects.equals(assignee.getItemAt(n).id,selectedAssignee))assignee.setSelectedIndex(n);model.clear();for(Issue i:loaded)if(selectedAssignee==null||selectedAssignee.equals(i.assigneeId()))model.addElement(i);footer.setText(model.size()+" issue(s) available");}catch(SQLException e){footer.setText("Could not load issues: "+e.getSQLState()+" / "+e.getErrorCode());}}
    private boolean containsAssignee(Long id){for(int n=0;n<assignee.getItemCount();n++)if(java.util.Objects.equals(assignee.getItemAt(n).id,id))return true;return false;}
    private <T> T selected(JComboBox<Object> box,Class<T> type){Object v=box.getSelectedItem();return type.isInstance(v)?type.cast(v):null;}
    private void create(){try{ProjectService projectsService=new ProjectService(new ProjectDao(),new UserDao());java.util.List<Project> projects=projectsService.getProjectsForUser(session);if(projects.isEmpty())throw new IllegalArgumentException("Join or create a project before creating an issue.");Object choice=JOptionPane.showInputDialog(this,"Choose project","Create issue",JOptionPane.PLAIN_MESSAGE,null,projects.toArray(),projects.get(0));if(choice==null)return;Project project=(Project)choice;java.util.List<ProjectMember> members=projectsService.getMembersForUser(session,project.id());IssueUpdate update=IssueFormDialog.show(this,null,members);if(update!=null){service.create(session,project.id(),update);refresh();}}catch(Exception e){show(e.getMessage());}}
    private void open(){Issue i=list.getSelectedValue();if(i!=null)new IssueDetailsDialog(this,service,session,i.id(),this::refresh).setVisible(true);}
    private void show(String m){JOptionPane.showMessageDialog(this,m,"Issues",JOptionPane.WARNING_MESSAGE);}
    private class Renderer extends DefaultListCellRenderer{public Component getListCellRendererComponent(JList<?> l,Object v,int i,boolean s,boolean f){JLabel x=(JLabel)super.getListCellRendererComponent(l,v,i,s,f);Issue q=(Issue)v;String statusColor=q.status()==IssueStatus.CLOSED?"#227e4e":q.status()==IssueStatus.IN_PROGRESS?"#3668dc":"#5a6478";String priorityColor=q.priority()==IssuePriority.CRITICAL||q.priority()==IssuePriority.HIGH?"#b23b3b":"#5a6478";x.setText("<html><b>#"+q.id()+" "+esc(q.title())+"</b>  <font color='"+priorityColor+"'>"+q.priority()+"</font>  <font color='"+statusColor+"'>"+q.status()+"</font><br>Project: "+esc(q.projectName())+" | Reporter: "+esc(q.reporterUsername())+" | Assignee: "+(q.assigneeUsername()==null?"Unassigned":esc(q.assigneeUsername()))+"</html>");x.setBorder(BorderFactory.createEmptyBorder(8,12,8,12));x.setFont(new Font("SansSerif",Font.PLAIN,13));return x;}private String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}}
    private static class AssigneeChoice{final Long id;final String name;AssigneeChoice(Long id,String name){this.id=id;this.name=name;}public String toString(){return name;}}
}
